          s: askG ? [['A pairs with T, so T is the same', 'A تقترن بـ T فنسبتهما واحدة', 'T:', a], ['The rest is C and G', 'الباقي C وG', '100 − ' + a + ' − ' + a + ' =', 100 - 2 * a], ['C and G are equal', 'C وG متساويتان', (100 - 2 * a) + ' ÷ 2 =', g]] : [['A pairs with T, one for one', 'A تقترن بـ T واحدة بواحدة', 'T:', a]],
